\begin{lemma}\label{lem:MeasureTheory.ae_eq_zero_of_integral_sq_eq_zero}
  \lean{MeasureTheory.ae_eq_zero_of_integral_sq_eq_zero}
If a real random variable \(X\) has integrable square and
\(\int X^2\,dP=0\), then \(X=0\) almost surely.
\end{lemma}

\begin{proof}
The function \(X^2\) is nonnegative.  The nonnegative-integral criterion
therefore gives \(X^2=0\) almost surely, and then \(X=0\) almost surely
pointwise on that event.
\end{proof}

\begin{lemma}\label{lem:Martingale.integral_sq_terminal_eq_zero_of_bounded_continuous_finiteVariation}
  \uses{def:Martingale, def:LocallyBoundedVariationOn, lem:Martingale.integral_increment_mul_increment_eq_zero, lem:BoundedVariationOn.sq_increment_sum_tendsto_zero_of_uniform_bound}
  \lean{MeasureTheory.Martingale.integral_sq_terminal_eq_zero_of_bounded_continuous_finiteVariation}
Let \(M\) be a real-valued true martingale with \(M_\bot=0\).  Fix a
deterministic time \(t>\bot\).  Assume that on the deterministic horizon
\([\bot,t]\) the paths are continuous, have bounded variation, and are bounded
by a deterministic integrable constant.  Then \(M_t^2\) is integrable and
\[
  \int M_t^2\,dP=0 .
\]
\end{lemma}

\begin{proof}
Choose deterministic finite partitions
\(\pi_n=\{\bot=s^n_0\le \cdots \le s^n_{k_n}=t\}\) whose mesh tends to zero.
For each partition, the telescoping identity gives
\[
  M_t-M_\bot
  =
  \sum_i (M_{s^n_{i+1}}-M_{s^n_i}).
\]
Expand the square of this finite sum.  After integration, every mixed term
vanishes by
Lemma~\ref{lem:Martingale.integral_increment_mul_increment_eq_zero}, so
\[
  \int M_t^2\,dP
  =
  \sum_i \int (M_{s^n_{i+1}}-M_{s^n_i})^2\,dP .
\]

For each sample point, continuity on \([\bot,t]\) implies that the largest
increment along \(\pi_n\) tends to zero.  Bounded variation on the same
horizon and
Lemma~\ref{lem:BoundedVariationOn.sq_increment_sum_tendsto_zero_of_uniform_bound}
then imply that the pathwise square-increment sums tend to zero.  The
deterministic boundedness of the stopped process supplies an integrable
dominating random variable for these square-increment sums.  Dominated
convergence sends their expectations to zero.  Since these expectations equal
\(\int M_t^2\,dP\), the terminal square integral is zero; the same deterministic
bound gives integrability of \(M_t^2\).
\end{proof}

\begin{lemma}\label{lem:Martingale.eq_zero_of_bounded_continuous_finiteVariation_core}
  \uses{def:Martingale, lem:MeasureTheory.ae_eq_zero_of_integral_sq_eq_zero}
  \lean{MeasureTheory.Martingale.eq_zero_of_bounded_continuous_finiteVariation_core}
Let \(M\) be a real-valued true martingale with \(M_\bot=0\).  Fix a
deterministic time \(t>\bot\).  Assume that on the deterministic horizon
\([\bot,t]\) the paths are continuous, have bounded variation, and are bounded
by a deterministic integrable constant.  If \(M_t^2\) is integrable and the
square-integral identity \(\int M_t^2\,dP=0\) has been proved, then \(M_t=0\)
almost surely.
\end{lemma}

\begin{proof}
Apply
Lemma~\ref{lem:MeasureTheory.ae_eq_zero_of_integral_sq_eq_zero} to the
integrable random variable \(M_t\).  The continuity, boundedness, martingale,
normalization, and finite-variation hypotheses are retained here because this
terminal lemma is called from the bounded-continuous finite-variation bridge;
the actual proof work left to that bridge is to derive the square-integral
identity from those hypotheses.
\end{proof}


\begin{lemma}\label{lem:Martingale.eq_zero_of_predictable_finiteVariation_bounded_continuous_reduction}
  \uses{def:Martingale, def:LocallyBoundedVariationOn, lem:LocallyBoundedVariationOn.exists_tendsto_left_univ, lem:Martingale.integral_sq_terminal_eq_zero_of_bounded_continuous_finiteVariation, lem:Martingale.eq_zero_of_bounded_continuous_finiteVariation_core}
  \lean{MeasureTheory.Martingale.eq_zero_of_predictable_finiteVariation_bounded_continuous_reduction}
Let \(M\) be a strongly predictable càdlàg true martingale with
\(M_\bot=0\), and suppose every path has locally bounded variation.  For
every deterministic time \(t>\bot\), the remaining analytic reduction proves
\(M_t=0\) almost surely.
\end{lemma}

\begin{proof}
The proof has four separate tasks.

First, remove predictable jumps at the fixed deterministic time \(t\).  Strong
predictability gives measurability of the time section with respect to the
predictable past sigma-algebra, not arbitrary \(\mathcal F_s\)-measurability.
Use the left-limit package
Lemma~\ref{lem:LocallyBoundedVariationOn.exists_tendsto_left_univ} together
with càdlàg paths to identify the left limit \(M_{t-}\), and apply martingale
conditional-expectation identities only at the past sigma-algebra level.

Second, localize on the deterministic horizon \([\bot,t]\).  Stopping at
bounded levels gives true martingales whose paths are bounded on the horizon,
remain càdlàg and strongly predictable, and preserve locally bounded
variation.  On the event where the localizing time exceeds \(t\), the stopped
process agrees with the original process at time \(t\).

Third, prove the bounded continuous square-integral premise.  For the bounded
continuous stopped process, apply
Lemma~\ref{lem:Martingale.integral_sq_terminal_eq_zero_of_bounded_continuous_finiteVariation}
to obtain integrability of \(M_t^2\) and the identity
\(\int M_t^2\,dP=0\).

Finally, use
Lemma~\ref{lem:Martingale.eq_zero_of_bounded_continuous_finiteVariation_core}
for each bounded stopped process, then let the stopping level tend to infinity
and intersect the resulting almost-sure events with the event on which the
localizing sequence eventually exceeds \(t\).
\end{proof}


